<?php
require_once __DIR__.'/../../includes/init.php';require_role('admin');require_once __DIR__.'/../../includes/layout.php';$pdo=db();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=(string)($_POST['action']??'');try{if(in_array($act,['add','update'],true)){$id=(int)($_POST['id_tarif']??0);$type=(string)($_POST['jenis_kendaraan']??'');$price=filter_var($_POST['tarif_per_jam']??null,FILTER_VALIDATE_INT);if(!in_array($type,['motor','mobil','lainnya'],true)||$price===false||$price===null||$price<0||$price>9999999999)throw new InvalidArgumentException('Jenis atau tarif tidak valid.');if($act==='add')$pdo->prepare('INSERT INTO tb_tarif(jenis_kendaraan,tarif_per_jam) VALUES(?,?)')->execute([$type,$price]);else $pdo->prepare('UPDATE tb_tarif SET jenis_kendaraan=?,tarif_per_jam=? WHERE id_tarif=?')->execute([$type,$price,$id]);log_activity('Mengubah tarif '.$type.' menjadi '.$price);flash('success','Tarif berhasil disimpan. Transaksi lama tetap memakai tarif snapshot.');redirect('admin/tarif/index.php');}if($act==='delete'){$id=input_int('id_tarif');$s=$pdo->prepare('SELECT COUNT(*) FROM tb_transaksi WHERE id_tarif=?');$s->execute([$id]);if((int)$s->fetchColumn())throw new InvalidArgumentException('Tarif sudah dipakai transaksi dan tidak dapat dihapus.');$pdo->prepare('DELETE FROM tb_tarif WHERE id_tarif=?')->execute([$id]);log_activity('Menghapus tarif ID '.$id);flash('success','Tarif dihapus.');redirect('admin/tarif/index.php');}throw new InvalidArgumentException('Aksi tidak valid.');}catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():(($e instanceof PDOException&&$e->getCode()==='23000')?'Setiap jenis kendaraan hanya boleh memiliki satu tarif.':'Operasi tarif gagal.');if(!($e instanceof InvalidArgumentException)&&!($e instanceof PDOException&&$e->getCode()==='23000'))error_log('[ParkirSTRD tarif] '.$e->getMessage());}}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM tb_tarif WHERE id_tarif=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:null;}$rows=$pdo->query('SELECT t.*, (SELECT COUNT(*) FROM tb_transaksi x WHERE x.id_tarif=t.id_tarif) AS dipakai FROM tb_tarif t ORDER BY FIELD(jenis_kendaraan,"motor","mobil","lainnya")')->fetchAll();render_header('Manajemen Tarif','tarif');?>
<div class="page-intro"><div><h2>Tarif parkir</h2><p>Tarif baru digunakan untuk kendaraan yang masuk setelah perubahan tersimpan.</p></div></div><?php if($error): ?><div class="alert alert-error"><?= h($error) ?></div><?php endif; ?><section class="panel"><div class="panel-heading"><div><h2><?= $edit?'Edit tarif':'Tambah tarif' ?></h2><p>Nilai tarif per jam dalam Rupiah, tidak boleh negatif.</p></div></div><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="<?= $edit?'update':'add' ?>"><?php if($edit): ?><input type="hidden" name="id_tarif" value="<?= (int)$edit['id_tarif'] ?>"><?php endif; ?><div class="field"><label>Jenis kendaraan</label><select name="jenis_kendaraan" required><?php foreach(['motor'=>'Motor','mobil'=>'Mobil','lainnya'=>'Lainnya'] as $k=>$v): ?><option value="<?= $k ?>" <?= ($edit['jenis_kendaraan']??'motor')===$k?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select></div><div class="field"><label>Tarif per jam (Rp)</label><input type="number" name="tarif_per_jam" min="0" max="9999999999" step="1" required value="<?= h($edit['tarif_per_jam']??'2000') ?>"></div><div class="form-actions"><?php if($edit): ?><a class="btn btn-secondary" href="<?= h(url('admin/tarif/index.php')) ?>">Batal</a><?php endif; ?><button class="btn btn-primary"><?= $edit?'Simpan tarif':'Tambah tarif' ?></button></div></form></section><section class="panel"><div class="panel-heading"><div><h2>Daftar tarif</h2><p><?= count($rows) ?> jenis tarif terkonfigurasi.</p></div></div><div class="table-wrap"><table><thead><tr><th>Jenis kendaraan</th><th>Tarif / jam</th><th>Transaksi terkait</th><th>Terakhir diperbarui</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td class="td-main"><?= h(ucfirst($r['jenis_kendaraan'])) ?></td><td><?= h(rupiah($r['tarif_per_jam'])) ?></td><td><?= (int)$r['dipakai'] ?></td><td><?= h(tanggal($r['updated_at'])) ?></td><td><div class="table-actions"><a class="btn btn-secondary btn-sm" href="<?= h(url('admin/tarif/index.php?edit='.(int)$r['id_tarif'])) ?>">Edit</a><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id_tarif" value="<?= (int)$r['id_tarif'] ?>"><button class="btn btn-danger btn-sm" <?= (int)$r['dipakai']?'disabled title="Sudah digunakan transaksi"':'' ?> data-confirm="Hapus jenis tarif ini?">Hapus</button></form></div></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="5"><div class="empty-state">Belum ada tarif.</div></td></tr><?php endif; ?></tbody></table></div></section><?php render_footer(); ?>